-- Supreme-only operational notification inbox.
-- Notifications are generated by trusted database events, not customer-facing APIs.
begin;

create table if not exists public.supreme_notifications (
  id uuid primary key default gen_random_uuid(),
  category text not null check (category in ('orders','payments','delivery','inventory')),
  severity text not null default 'info' check (severity in ('info','warning','critical')),
  event_key text not null unique,
  title text not null check (char_length(title) between 1 and 120),
  body text not null check (char_length(body) between 1 and 500),
  href text not null default '/supreme',
  entity_type text,
  entity_id text,
  created_at timestamptz not null default now(),
  read_at timestamptz,
  read_by uuid references auth.users(id) on delete set null
);

create index if not exists supreme_notifications_created_idx
  on public.supreme_notifications(created_at desc, id desc);
create index if not exists supreme_notifications_unread_idx
  on public.supreme_notifications(created_at desc)
  where read_at is null;

alter table public.supreme_notifications enable row level security;
revoke all on public.supreme_notifications from public, anon, authenticated;
grant select, insert, update on public.supreme_notifications to service_role;

create or replace function private.create_supreme_order_notifications()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if tg_op = 'INSERT' then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'orders', 'info', 'order.created:' || new.id::text,
      'নতুন অর্ডার এসেছে',
      'অর্ডার ' || new.order_number || ' · ৳' || new.total::text,
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;

    if new.payment_status::text = 'verification_pending' then
      insert into public.supreme_notifications(
        category, severity, event_key, title, body, href, entity_type, entity_id
      ) values (
        'payments', 'warning', 'payment.review:' || new.id::text,
        'পেমেন্ট যাচাই প্রয়োজন',
        'অর্ডার ' || new.order_number || ' এর পেমেন্ট যাচাই অপেক্ষমাণ।',
        '/admin/orders', 'order', new.id::text
      )
      on conflict (event_key) do nothing;
    end if;

    return new;
  end if;

  if new.payment_status::text is distinct from old.payment_status::text
     and new.payment_status::text in ('failed', 'refunded') then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'payments',
      case when new.payment_status::text = 'failed' then 'critical' else 'warning' end,
      'payment.' || new.payment_status::text || ':' || new.id::text,
      case when new.payment_status::text = 'failed' then 'পেমেন্ট ব্যর্থ হয়েছে' else 'পেমেন্ট রিফান্ড হয়েছে' end,
      'অর্ডার ' || new.order_number || ' · ' || new.payment_status::text,
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  if new.delivery_status::text is distinct from old.delivery_status::text
     and new.delivery_status::text in ('failed', 'returned') then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'delivery', 'critical',
      'delivery.' || new.delivery_status::text || ':' || new.id::text,
      case when new.delivery_status::text = 'failed' then 'ডেলিভারিতে সমস্যা হয়েছে' else 'পার্সেল ফেরত এসেছে' end,
      'অর্ডার ' || new.order_number || ' · ' || new.delivery_status::text,
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  if new.status::text is distinct from old.status::text
     and new.status::text = 'cancelled' then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'orders', 'warning', 'order.cancelled:' || new.id::text,
      'অর্ডার বাতিল হয়েছে',
      'অর্ডার ' || new.order_number || ' বাতিল করা হয়েছে।',
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  return new;
end;
$function$;

revoke all on function private.create_supreme_order_notifications() from public, anon, authenticated;

drop trigger if exists orders_create_supreme_notifications on public.orders;
create trigger orders_create_supreme_notifications
after insert or update of status, payment_status, delivery_status on public.orders
for each row execute function private.create_supreme_order_notifications();

create or replace function private.create_supreme_low_stock_notification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if new.stock <= new.low_stock_threshold
     and (tg_op = 'INSERT' or old.stock > old.low_stock_threshold) then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'inventory',
      case when new.stock = 0 then 'critical' else 'warning' end,
      'inventory.low_stock:' || new.id::text || ':' || new.stock::text,
      case when new.stock = 0 then 'পণ্যের স্টক শেষ' else 'পণ্যের স্টক কমে গেছে' end,
      new.name || ' · অবশিষ্ট ' || new.stock::text || 'টি',
      '/admin/inventory', 'product', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  return new;
end;
$function$;

revoke all on function private.create_supreme_low_stock_notification() from public, anon, authenticated;

drop trigger if exists products_create_supreme_low_stock_notification on public.products;
create trigger products_create_supreme_low_stock_notification
after insert or update of stock on public.products
for each row execute function private.create_supreme_low_stock_notification();

commit;
